    const numVal = v => {
        const m = String(v).trim().replace('−', '-').replace(',', '.').match(/^(-?\d+(?:\.\d+)?)(?:\/(-?\d+(?:\.\d+)?))?$/);
        return m ? parseFloat(m[1]) / (m[2] ? parseFloat(m[2]) : 1) : NaN;
    };
    const fmt6 = n => Number(n.toFixed(6));
    const uniq3 = (correct, wrong) => {
        const cNum = numVal(correct);
        const seenS = new Set([String(correct)]), seenN = new Set([cNum]), out = [];
        wrong.filter(w => {
            if (w === null || w === undefined) return false;
            if (typeof w === 'number' && !Number.isFinite(w)) return false;
            return typeof w !== 'string' || w.trim() !== '';
        }).forEach(w => {
            const s = String(w), n = numVal(w);
            if (out.length < 3 && !seenS.has(s) && (Number.isNaN(n) || !seenN.has(n))) { seenS.add(s); if (!Number.isNaN(n)) seenN.add(n); out.push(w); }
        });
        if (out.length < 3) {
            if (!Number.isFinite(cNum)) throw new Error('текстовый верный ответ: недостаточно уникальных неверных вариантов');
            let k = 10;
            while (out.length < 3) { const c = fmt6(cNum + k); if (!seenN.has(c) && !seenS.has(String(c))) { seenN.add(c); seenS.add(String(c)); out.push(c); } k += 10; }
        }
        return out;
    };
