        const seen = new Set([correct]), out = [];
        wrong.forEach(w => { if (ok(w) && out.length < 3 && !seen.has(w)) { seen.add(w); out.push(w); } });
        if (out.length < 3) throw new Error('недостаточно уникальных текстовых вариантов');
        return { q, correct, wrong: out, exp };
